	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOwnRecentJobsRow{}
	for rows.Next() {
		var i ListOwnRecentJobsRow
		if err := rows.Scan(
			&i.ID,
			&i.DisplayID,
			&i.Title,
			&i.MachineName,
			&i.StartedAt,
			&i.EndedAt,
			&i.Status,
			&i.EffectivePrice,
			&i.Own,
			&i.BillingState,
			&i.OrderReference,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
