const searchBillingParties = `-- name: SearchBillingParties :many
SELECT party_kind, party_id, display_name, organization_kind, pricing_group_id, pricing_group_name,
       pricing_group_assignment_version FROM (
    SELECT 'person'::text AS party_kind, p.id AS party_id, btrim(p.first_name || ' ' || p.last_name) AS display_name,
           NULL::text AS organization_kind, NULL::uuid AS pricing_group_id, NULL::text AS pricing_group_name,
           0::bigint AS pricing_group_assignment_version,
           lower(p.last_name || ' ' || p.first_name) AS ordering
    FROM people p
    WHERE $1::text = '' OR lower(p.first_name || ' ' || p.last_name) LIKE '%' || lower($1::text) || '%'
    UNION ALL
    SELECT 'organization'::text, o.id, o.name, o.kind, pg.id, pg.name,
           COALESCE(a.version, 0)::bigint, lower(o.name)
    FROM organizations o
    LEFT JOIN organization_pricing_group_assignments a ON a.organization_id = o.id
    LEFT JOIN pricing_groups pg ON pg.id = a.pricing_group_id
    WHERE o.active AND ($1::text = '' OR lower(o.name) LIKE '%' || lower($1::text) || '%')
) parties
ORDER BY ordering, party_id
LIMIT $2
`

type SearchBillingPartiesParams struct {
	Search    string
	PageLimit int32
}

type SearchBillingPartiesRow struct {
	PartyKind                     string
	PartyID                       uuid.UUID
	DisplayName                   string
	OrganizationKind              *string
	PricingGroupID                *uuid.UUID
	PricingGroupName              *string
	PricingGroupAssignmentVersion int64
}

func (q *Queries) SearchBillingParties(ctx context.Context, arg SearchBillingPartiesParams) ([]SearchBillingPartiesRow, error) {
	rows, err := q.db.Query(ctx, searchBillingParties, arg.Search, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchBillingPartiesRow{}
	for rows.Next() {
		var i SearchBillingPartiesRow
		if err := rows.Scan(
			&i.PartyKind,
			&i.PartyID,
			&i.DisplayName,
			&i.OrganizationKind,
			&i.PricingGroupID,
			&i.PricingGroupName,
			&i.PricingGroupAssignmentVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

